export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) throw new Error('Invalid amount');
    if (!currency || currency.length !== 3) throw new Error('Invalid currency code');
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase();
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (other.currency !== this.currency) throw new Error('Currency mismatch');
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return other instanceof Money && this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

interface DomainEvent {
  type: string;
  orderId: string;
  occurredAt: Date;
  payload?: Record<string, unknown>;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private _items: OrderItem[] = [];
  private events: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (!id || !customerId) throw new Error('Order requires id and customerId');
    this.id = id;
    this.customerId = customerId;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') throw new Error('Cannot modify a non-pending order');
    if (!productId) throw new Error('productId is required');
    if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('Quantity must be a positive integer');
    if (!(price instanceof Money)) throw new Error('price must be a Money');
    const existing = this._items.find((i) => i.id === productId);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }
    this.events.push({
      type: 'OrderItemAdded',
      orderId: this.id,
      occurredAt: new Date(),
      payload: { productId, quantity, price: price.amount, currency: price.currency },
    });
  }

  pay(): void {
    if (this._status !== 'PENDING') throw new Error(`Cannot pay order in status ${this._status}`);
    if (this._items.length === 0) throw new Error('Cannot pay an empty order');
    this._status = 'PAID';
    this.events.push({ type: 'OrderPaid', orderId: this.id, occurredAt: new Date() });
  }

  ship(): void {
    if (this._status !== 'PAID') throw new Error(`Cannot ship order in status ${this._status}`);
    this._status = 'SHIPPED';
    this.events.push({ type: 'OrderShipped', orderId: this.id, occurredAt: new Date() });
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error(`Cannot cancel order in status ${this._status}`);
    }
    this._status = 'CANCELLED';
    this.events.push({ type: 'OrderCancelled', orderId: this.id, occurredAt: new Date() });
  }

  getTotal(): Money {
    if (this._items.length === 0) return new Money(0, 'USD');
    return this._items
      .map((i) => new Money(i.price.amount * i.quantity, i.price.currency))
      .reduce((sum, next) => sum.add(next));
  }

  getDomainEvents(): any[] {
    return [...this.events];
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

export class InMemoryOrderRepository implements IOrderRepository {
  private store = new Map<string, string>();

  private serialize(order: Order): string {
    return JSON.stringify({
      id: order.id,
      customerId: order.customerId,
      status: order.status,
      items: order.items.map((i) => ({
        id: i.id,
        quantity: i.quantity,
        amount: i.price.amount,
        currency: i.price.currency,
      })),
    });
  }

  private deserialize(raw: string): Order {
    const data = JSON.parse(raw);
    const order = new Order(data.id, data.customerId);
    for (const item of data.items) {
      order.addItem(item.id, item.quantity, Money.of(item.amount, item.currency));
    }
    if (data.status === 'PAID') order.pay();
    else if (data.status === 'SHIPPED') { order.pay(); order.ship(); }
    else if (data.status === 'CANCELLED') order.cancel();
    return order;
  }

  async findById(id: string): Promise<Order | null> {
    const raw = this.store.get(id);
    return raw ? this.deserialize(raw) : null;
  }

  async save(order: Order): Promise<void> {
    this.store.set(order.id, this.serialize(order));
  }
}

