export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class InvalidOperationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidOperationError';
  }
}

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) throw new InvalidOperationError('Amount must be finite');
    if (amount < 0) throw new InvalidOperationError('Amount cannot be negative');
    if (!currency || currency.length !== 3) throw new InvalidOperationError('Currency must be a 3-letter ISO code');
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase();
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new InvalidOperationError(`Cannot add ${other.currency} to ${this.currency}`);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

interface DomainEvent {
  readonly type: string;
  readonly orderId: string;
  readonly occurredAt: Date;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private _items: OrderItem[] = [];
  private _events: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (!id) throw new InvalidOperationError('Order id is required');
    if (!customerId) throw new InvalidOperationError('customerId is required');
    this.id = id;
    this.customerId = customerId;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new InvalidOperationError('Cannot modify items on a non-pending order');
    }
    if (!productId) throw new InvalidOperationError('productId is required');
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvalidOperationError('Quantity must be a positive integer');
    }
    const existing = this._items.find((i) => i.id === productId);
    if (existing) {
      this._items = this._items.map((i) =>
        i.id === productId ? { ...i, quantity: i.quantity + quantity } : i
      );
      return;
    }
    this._items = [...this._items, { id: productId, quantity, price }];
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new InvalidOperationError(`Cannot pay order in status ${this._status}`);
    }
    if (this._items.length === 0) {
      throw new InvalidOperationError('Cannot pay an empty order');
    }
    this._status = 'PAID';
    this._events.push({ type: 'OrderPaid', orderId: this.id, occurredAt: new Date() });
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new InvalidOperationError(`Cannot ship order in status ${this._status}`);
    }
    this._status = 'SHIPPED';
    this._events.push({ type: 'OrderShipped', orderId: this.id, occurredAt: new Date() });
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new InvalidOperationError(`Cannot cancel order in status ${this._status}`);
    }
    this._status = 'CANCELLED';
    this._events.push({ type: 'OrderCancelled', orderId: this.id, occurredAt: new Date() });
  }

  getTotal(): Money {
    if (this._items.length === 0) return new Money(0, 'USD');
    const currency = this._items[0]?.price.currency ?? 'USD';
    return this._items.reduce(
      (sum, item) => sum.add(new Money(item.price.amount * item.quantity, item.price.currency)),
      new Money(0, currency)
    );
  }

  getDomainEvents(): DomainEvent[] {
    return [...this._events];
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}
